CREATE TABLE parent_communication_contacts(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES schools(id),user_id BIGINT NOT NULL CHECK(user_id>0),category VARCHAR(32) NOT NULL,contact_type VARCHAR(24) NOT NULL DEFAULT 'PARENT_FACING' CHECK(contact_type IN('PARENT_FACING','ACADEMIC_HEAD')),display_label VARCHAR(120) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_by_user_id BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,user_id,category,contact_type));
CREATE TABLE parent_communication_policies(organization_id BIGINT PRIMARY KEY REFERENCES schools(id),max_open_threads INTEGER NOT NULL DEFAULT 3 CHECK(max_open_threads BETWEEN 1 AND 20),max_new_threads_7_days INTEGER NOT NULL DEFAULT 5 CHECK(max_new_threads_7_days BETWEEN 1 AND 50),head_escalation_school_days INTEGER NOT NULL DEFAULT 2 CHECK(head_escalation_school_days BETWEEN 1 AND 10),updated_by_user_id BIGINT NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE parent_communication_threads(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL REFERENCES schools(id),guardian_user_id BIGINT NOT NULL CHECK(guardian_user_id>0),student_user_id BIGINT NOT NULL CHECK(student_user_id>0),contact_user_id BIGINT NOT NULL CHECK(contact_user_id>0),contact_kind VARCHAR(24) NOT NULL CHECK(contact_kind IN('ASSIGNED_TEACHER','CONFIGURED_STAFF','ACADEMIC_HEAD','PRINCIPAL')),category VARCHAR(32) NOT NULL,subject VARCHAR(160) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','RESOLVED','CLOSED')),escalation_level VARCHAR(24) NOT NULL DEFAULT 'NONE' CHECK(escalation_level IN('NONE','HEAD_REQUESTED','HEAD','PRINCIPAL')),head_eligible_at TIMESTAMPTZ NOT NULL,principal_authorized_at TIMESTAMPTZ,last_message_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(id,organization_id));
CREATE UNIQUE INDEX uk_parent_communication_open_issue ON parent_communication_threads(organization_id,guardian_user_id,student_user_id,contact_user_id,category) WHERE status='OPEN';
CREATE INDEX idx_parent_communication_guardian ON parent_communication_threads(organization_id,guardian_user_id,last_message_at DESC);
CREATE INDEX idx_parent_communication_contact ON parent_communication_threads(organization_id,contact_user_id,status,last_message_at DESC);
CREATE TABLE parent_communication_messages(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL,thread_id BIGINT NOT NULL,sender_user_id BIGINT NOT NULL CHECK(sender_user_id>0),body VARCHAR(4000) NOT NULL CHECK(BTRIM(body)<>''),idempotency_key VARCHAR(120) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(id,organization_id),UNIQUE(organization_id,sender_user_id,idempotency_key),FOREIGN KEY(thread_id,organization_id) REFERENCES parent_communication_threads(id,organization_id) ON DELETE CASCADE);
CREATE TABLE parent_communication_participants(organization_id BIGINT NOT NULL,thread_id BIGINT NOT NULL,user_id BIGINT NOT NULL CHECK(user_id>0),participant_role VARCHAR(24) NOT NULL CHECK(participant_role IN('GUARDIAN','CONTACT','HEAD','PRINCIPAL')),last_read_message_id BIGINT,left_at TIMESTAMPTZ,joined_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(organization_id,thread_id,user_id),FOREIGN KEY(thread_id,organization_id) REFERENCES parent_communication_threads(id,organization_id) ON DELETE CASCADE,FOREIGN KEY(last_read_message_id,organization_id) REFERENCES parent_communication_messages(id,organization_id));
CREATE TABLE parent_communication_audit(id BIGSERIAL PRIMARY KEY,organization_id BIGINT NOT NULL,thread_id BIGINT NOT NULL,actor_user_id BIGINT NOT NULL,action VARCHAR(40) NOT NULL,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(thread_id,organization_id) REFERENCES parent_communication_threads(id,organization_id) ON DELETE CASCADE);
